package test;

import org.eclipse.core.internal.properties.PropertyManager2;
import org.eclipse.core.resources.IFile;
import org.eclipse.core.resources.IProject;
import org.eclipse.core.resources.IResource;
import org.eclipse.core.runtime.CoreException;

// Mocks to make it compilable without Eclipse platform dependencies
// (Normally these would be imported from the Eclipse platform)
interface IProjectMock extends IProject {}
interface IResourceMock extends IResource {
    // Constants are normally static final, but interfaces can have them.
    // Re-declaring for self-contained example clarity.
    int DEPTH_INFINITE = IResource.DEPTH_INFINITE;
    int DEPTH_ZERO = IResource.DEPTH_ZERO;
}
interface IFileMock extends IResourceMock, IFile {
    @Override
    IProject getProject();
}
class CoreExceptionMock extends CoreException { public CoreExceptionMock(String message) { super(message); } }

// Mock IFile implementation with a non-null project
class MockFileWithProject implements IFileMock {
    @Override public IProject getProject() { return () -> "mockProject"; }
}

// Mock IFile implementation with a null project
class MockFileWithoutProject implements IFileMock {
    @Override public IProject getProject() { return null; }
}

// Mock IResource that is not an IFile
class MockResource implements IResourceMock {}

// Mock PropertyManager2
class PropertyManager2Mock extends PropertyManager2 {
    @Override public void deleteProperties(IResource target, int depth) throws CoreException { /* Do nothing */ }
}

public class Example {
    PropertyManager2Mock manager = new PropertyManager2Mock();

    public void cleanupCandidate() throws CoreExceptionMock {
        IFileMock fileWithProject = new MockFileWithProject();
        IFileMock fileWithoutProject = new MockFileWithoutProject();
        IResourceMock genericResource = new MockResource();

        // Case 1: IFile with non-null project -> should be changed
        manager.deleteProperties(fileWithProject, IResource.DEPTH_INFINITE);

        // Case 2: IFile with null project -> should NOT be changed
        manager.deleteProperties(fileWithoutProject, IResource.DEPTH_INFINITE);

        // Case 3: IResource (not IFile) -> should NOT be changed
        manager.deleteProperties(genericResource, IResource.DEPTH_INFINITE);
    }
}

