class MyClass {
    String myString = "true";
    int myInt = 1;

    void noMatchMethod() {
        // This is a String comparison, not boolean. Should not match.
        if (myString == "true") {
            System.out.println("String equality check.");
        }
        // This is an int comparison, not boolean. Should not match.
        if (myInt == 1) {
            System.out.println("Integer equality check.");
        }
    }

    boolean methodWithSideEffect() {
        System.out.println("Executing side effect...");
        return true;
    }

    void sideEffectMethod() {
        // This has a side effect, so the rule with hasNoSideEffect() guard
        // should explicitly NOT match this even though it's boolean == true.
        if (methodWithSideEffect() == true) {
            System.out.println("This should NOT be simplified to 'if (methodWithSideEffect())'.");
        }
        // Similarly for '== false'
        if (methodWithSideEffect() == false) {
            System.out.println("This should NOT be simplified to 'if (!methodWithSideEffect())'.");
        }
    }
}
